UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals who use well developed marketing and communication skills and a broad knowledge base in a wide variety of contexts. This qualification applies to individuals in full-time marketing roles, as well as those who are responsible for an organisation’s marketing in addition to other duties.</p><p>Individuals in these roles apply solutions to a defined range of unpredictable problems and analyse and evaluate information from a variety of sources.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Digital Marketing Expert</li><li>Social Media Expert</li><li>SEO Professional</li><li>Marketing Manager and many more professions. </li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBCMM411</p></td><td><p>Make presentations</p></td><td><p>Core</p></td></tr><tr><td><p>BSBCRT412</p></td><td><p>Articulate, present and debate ideas</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG433</p></td><td><p>Undertake marketing activities</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG435</p></td><td><p>Analyse consumer behaviour</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG439</p></td><td><p>Develop and apply knowledge of communications industry</p></td><td><p>Core</p></td></tr><tr><td><p>BSBWRT411</p></td><td><p>Write complex documents</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG431</p></td><td><p>Assess marketing opportunities</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBTWK401</p></td><td><p>Build and maintain business relationships</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBXCM401</p></td><td><p>Apply communication strategies in the workplace</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBOPS405</p></td><td><p>Organise business meetings</p></td><td><p>Elective</p></td></tr><tr><td><p>SIRXECM002</p></td><td><p>Prepare digital content</p></td><td><p>Elective</p></td></tr><tr><td><p>SIRXMKT006</p></td><td><p>Develop a social media strategy</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of marketing and communication roles in a range of industry areas.</p><p>Students who complete this course may wish to continue their education into the BSB50620 Diploma of Marketing and Communication or a range of Diploma qualifications, as well as higher education qualifications in marketing and communication.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 11000,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/certificate-iv-in-marketing-and-communication',
    updated_at = NOW()
WHERE cricos_course_code = '104957D';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals who apply knowledge, practical skills and experience in leadership and management across a range of enterprise and industry contexts.</p><p>Individuals at this level display initiative and judgement in planning, organising, implementing, and monitoring their own workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements.</p><p>They may plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse, and synthesise information from a variety of sources.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Human Resources Manager</li><li>Team Leader</li><li>Business Manager</li><li>Sales Manager</li><li>Office Manager</li></ul><p>And many more administrative and professional roles. </p></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBCMM511</p></td><td><p>Communicate with influence</p></td><td><p>Core</p></td></tr><tr><td><p>BSBCRT511</p></td><td><p>Develop critical thinking in others</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR523</p></td><td><p>Lead and manage effective workplace relationships</p></td><td><p>Core</p></td></tr><tr><td><p>BSBOPS502</p></td><td><p>Manage business operational plans</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPEF502</p></td><td><p>Develop and use emotional intelligence</p></td><td><p>Core</p></td></tr><tr><td><p>BSBTWK502</p></td><td><p>Manage team effectiveness</p></td><td><p>Core</p></td></tr><tr><td><p>BSBCRT512</p></td><td><p>Originate and develop concepts</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBOPS504</p></td><td><p>Manage business risk</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBSTR502</p></td><td><p>Facilitate continuous improvement</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBSUS511</p></td><td><p>Develop workplace policies and procedures for sustainability</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBHRM524</p></td><td><p>Coordinate workforce plan implementation</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBHRM522</p></td><td><p>Manage employee and industrial relations</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of leadership and management roles in a range of industry areas.</p><p>Students who complete this course may wish to continue their education into the BSB60420 Advanced Diploma of Leadership and Management or a range of Advanced Diploma qualifications, as well as higher education qualifications in leadership and management.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 15000,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/diploma-of-leadership-and-management',
    updated_at = NOW()
WHERE cricos_course_code = '103721K';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals who use a sound theoretical knowledge base in marketing and communication and who demonstrate a range of skills to ensure that functions are effectively conducted in an organisation or business area. Typically, the individuals would have responsibility for the work of other staff and lead teams.</p><p>This qualification applies to individuals in full-time marketing roles, as well as those who are responsible for an organisation’s marketing in addition to other duties.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Digital Marketing Expert</li><li>Social Media Expert</li><li>SEO Professional</li><li>Marketing Manager and many more professions. </li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBMKG541</p></td><td><p>Identify and evaluate marketing opportunities</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG542</p></td><td><p>Establish and monitor the marketing mix</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG552</p></td><td><p>Design and develop marketing communication plans</p></td><td><p>Core</p></td></tr><tr><td><p>BSBMKG555</p></td><td><p>Write persuasive copy</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG430</p></td><td><p>Undertake project work</p></td><td><p>Core</p></td></tr><tr><td><p>SIRXMKT007</p></td><td><p>Develop a digital marketing plan</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBTEC404</p></td><td><p>Use digital technologies to collaborate in a work environment</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBMKG553</p></td><td><p>Develop public relations campaigns</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBCMM511</p></td><td><p>Communicate with influence</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBFIN501</p></td><td><p>Manage budgets and financial plans</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBOPS504</p></td><td><p>Manage business risk</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBMKG547</p></td><td><p>Develop strategies to monetise digital engagement</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in marketing and communication in a range of industry areas.</p><p>Students who complete this course may wish to continue their education into the BSB60520 Advanced Diploma of Marketing and Communication or a range of Advanced Diploma qualifications, as well as higher education qualifications in marketing and communication.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 16500,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>The Training Package requires the following:</p><p>Entry to this qualification is limited to those who:</p><p>Have completed BSB42415 Certificate IV in Marketing and Communication</p><p><strong>or</strong></p><p>Have completed the following units (or equivalent competencies):</p><ul><li>BSBCMM411 Make presentations;</li><li>BSBCRT412 Articulate, present and debate ideas;</li><li>BSBMKG433 Undertake marketing activities;</li><li>BSBMKG435 Analyse consumer behaviour;</li><li>BSBMKG439 Develop and apply knowledge of communications industry; and</li><li>BSBWRT411 Write complex documents.</li></ul><p>Equivalent competencies are predecessors to these units, which have been mapped as equivalent.</p><p><strong>or</strong></p><p>Have two years equivalent full-time relevant work experience.</p><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/diploma-of-marketing-and-communication',
    updated_at = NOW()
WHERE cricos_course_code = '104958C';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals who apply project management skills and knowledge in a variety of contexts, across a number of industry sectors. The job roles that relate to this qualification may include Project Manager and Project Team Leader.</p><p>Individuals in these roles have project leadership and management roles and are responsible for achieving project objectives. They possess a sound theoretical knowledge base and use a range of specialised, technical, and managerial competencies to initiate, plan, execute and evaluate their own work and/or the work of others.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Project Contracts Manager </li><li>Monitoring and Evalutaion Manager and many more.</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBPMG530</p></td><td><p>Manage project scope</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG531</p></td><td><p>Manage project time</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG532</p></td><td><p>Manage project quality</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG533</p></td><td><p>Manage project cost</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG534</p></td><td><p>Manage project human resources</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG535</p></td><td><p>Manage project information and communication</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG536</p></td><td><p>Manage project risk</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG540</p></td><td><p>Manage project integration</p></td><td><p>Core</p></td></tr><tr><td><p>BSBCMM511</p></td><td><p>Communicate with influence</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBCRT511</p></td><td><p>Develop critical thinking in others</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBLDR522</p></td><td><p>Manage people performance</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBOPS501</p></td><td><p>Manage business resources</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of project management roles in a range of industry areas.</p><p>Students who complete this course may wish to continue their education into the BSB60720 Advanced Diploma of Program Management or a range of Advanced Diploma qualifications, as well as higher education qualifications in project and leadership management.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 16500,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>Educated for 5 years in an English – speaking country.</li><li>Successful completion of an English Placement Test at IELTS level 6.0</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p></div></div> </details>',
