UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p><p>Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p><p>They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Office Manager</li><li>Human Resources Professional</li><li>Operations Manager</li><li>Sales &amp; Marketing Manager</li><li>Call Centre Manager &amp; many more.</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBCRT611</p></td><td><p>Apply critical thinking for complex problem solving</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR601</p></td><td><p>Lead and manage organisational change</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR602</p></td><td><p>Provide leadership across the organisation</p></td><td><p>Core</p></td></tr><tr><td><p>BSBOPS601</p></td><td><p>Develop and implement business plans</p></td><td><p>Core</p></td></tr><tr><td><p>BSBSTR601</p></td><td><p>Manage innovation and continuous improvement</p></td><td><p>Core</p></td></tr><tr><td><p>BSBSUS601</p></td><td><p>Lead corporate social responsibility</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBCMM511</p></td><td><p>Communicate with influence</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBHRM613</p></td><td><p>Contribute to the development of learning and development strategies</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBHRM614</p></td><td><p>Contribute to strategic workforce planning</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBCRT511</p></td><td><p>Develop critical thinking in others</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in leadership and management roles in a range of industry areas.</p><p>Students who complete this course may wish to continue their education into the BSB80120 Graduate Diploma of Management (Learning)or a range of Graduate Diploma qualifications, as well as higher education qualifications in business or management.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
