UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.<br/>This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>RTO Manager</li><li>RTO Director</li></ul><p>And many more administrative and professional roles. </p></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td><p>Unit Code and Unit Name</p></td><td><p>Core / Elective</p></td></tr><tr><td><p>BSBHRM613 Contribute to the development of learning and development strategies</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR811 Lead strategic transformation</p></td><td><p>Core</p></td></tr><tr><td><p>TAELED803 Implement improved learning practice</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR601 Lead and manage organisational change</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBOPS601 Develop and implement business plans</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBSTR801 Lead innovative thinking and practice</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBCRT611 Apply critical thinking for complex problem solving</p></td><td><p>Elective</p></td></tr><tr><td><p>PSPMGT012 Facilitate knowledge management</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are as a Leader or Manager in organisations where learning is used to build organisational capability in a range of industry areas.</p><p>Students who complete this course may wish to continue their education into a range of higher education qualifications in organisational learning and development.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures</p></div></div> </details>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 20000,
