    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>Educated for 5 years in an English – speaking country.</li><li>Successful completion of an English Placement Test at IELTS level 6.0</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/course/graduate-diploma-of-management-learning',
    updated_at = NOW()
WHERE cricos_course_code = '112350B';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of educators in early childhood education and care who work in regulated children’s education and care services in Australia. They support children’s wellbeing, and development in the context of an approved learning framework. Educators use a range of well-developed skills and knowledge using discretion and judgment when carrying out their work in the context of established policies and procedures. They may work independently or under the guidance of others, though in some contexts that guidance may not be on-site.</p><p>Early childhood educators work in long day care centres, family day care, pre-schools or kindergartens.</p><p>Under the Education and Care Services National Law (2011) the Australian Children’s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here: <a href="https://web.archive.org/web/20260125084438/http://www.acecqa.gov.au/" rel="noopener" target="_blank">www.acecqa.gov.au</a>.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Family Day Care Educator</li><li>Kindergarten Assistant</li><li>Long Day Care Educator</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td>S/N</td><td>Unit Code</td><td>CHC30121 Certificate III in Early Childhood Education and Care</td><td>Core Units/ Elective Units</td><td>Hours</td></tr><tr><td>1</td><td>CHCECE034</td><td>Use an approved learning framework to guide practice</td><td>Core</td><td>40</td></tr><tr><td>2</td><td>CHCECE031</td><td>Support children’s health, safety and wellbeing</td><td>Core</td><td>40</td></tr><tr><td>3</td><td>CHCECE055</td><td>Meet legal and ethical obligations in children’s education and care</td><td>Core</td><td>40</td></tr><tr><td>4</td><td>HLTWHS001</td><td>Participate in workplace health and safety</td><td>Core</td><td>20</td></tr><tr><td>5</td><td>HLTAID012</td><td>Provide First Aid in an education and care setting</td><td>Core</td><td>20</td></tr><tr><td>6</td><td>CHCPRT001</td><td>Identify and respond to children and young people at risk</td><td>Core</td><td>40</td></tr><tr><td>7</td><td>CHCECE032</td><td>Nurture babies and toddlers</td><td>Core</td><td>40</td></tr><tr><td>8</td><td>CHCDIV001</td><td>Work with diverse people</td><td>Elective</td><td>40</td></tr><tr><td>9</td><td>CHCECE030</td><td>Support inclusion and diversity</td><td>Core</td><td>40</td></tr><tr><td>10</td><td>CHCECE033</td><td>Develop positive and respectful relationships with children</td><td>Core</td><td>40</td></tr><tr><td>11</td><td>CHCECE035</td><td>Support the holistic learning and development of children</td><td>Core</td><td>40</td></tr><tr><td>12</td><td>CHCECE036</td><td>Provide experiences to support children’s play and learning</td><td>Core</td><td>40</td></tr><tr><td>13</td><td>CHCECE037</td><td>Support children to connect with the natural environment</td><td>Core</td><td>40</td></tr><tr><td>14</td><td>CHCECE038</td><td>Observe children to inform practice</td><td>Core</td><td>40</td></tr><tr><td>15</td><td>CHCECE054</td><td>Encourage understanding of Aboriginal and/or Torres Strait Islander peoples’ cultures</td><td>Core</td><td>40</td></tr><tr><td>16</td><td>CHCECE056</td><td>Work effectively in children’s education and care</td><td>Core</td><td>40</td></tr><tr><td>17</td><td>BSBSTR401</td><td>Promote innovation in team environments</td><td>Elective</td><td>40</td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are as an Educator in an Early Childhood Education and Care setting.</p><p>Students who complete this course may wish to continue their education into the CHC50121Diploma of Early Childhood Education and Care.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 11900,
    enrolment_fee = 200,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>Educated for 5 years in an English – speaking country.</li><li>Successful completion of an English Placement Test at IELTS level 6.0</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p></div></div> </details>',
