UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals in the community, home or residential care setting who work under supervision and delegation as a part of a multi-disciplinary team, following an individualised plan to provide person-centred support to people who may require support due to ageing, disability or some other reason.</p><p>These individuals take responsibility for their own outputs within the scope of their job role and delegation. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Aged Care Worker</li><li>Disability Support Worker</li><li>Home Care Assistant</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td><p><strong>Code</strong></p></td><td><p><strong>Core/Elective</strong></p></td></tr><tr><td><p>CHCCCS031 Provide individualised support</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS038 Facilitate the empowerment of people receiving support</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS041 Recognise healthy body systems</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCOM005 Communicate and work in health or community services</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS040 Support independence and wellbeing</p></td><td><p>Core</p></td></tr><tr><td><p>HLTINF006 Apply basic principles and practices of infection prevention and control</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIV001 Work with diverse people</p></td><td><p>Core</p></td></tr><tr><td><p>CHCLEG001 Work legally and ethically</p></td><td><p>Core</p></td></tr><tr><td><p>CHCAGE011 Provide support to people living with dementia</p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p>CHCAGE013 Work effectively in aged care</p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p>HLTWHS002 Follow safe work practices for direct client care</p></td><td><p>Core</p></td></tr><tr><td><p>CHCPAL003 Deliver care services using a palliative approach</p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p>CHCDIS011 Contribute to ongoing skills development using a strengths-based approach</p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p>CHCDIS012 Support community participation and social inclusion</p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p>CHCDIS020 Work effectively in disability support</p></td><td><p><strong>Elective</strong></p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are as a direct support worker in aged care, disability, home and community care or other direct care work in the community services industry.</p><p>Students who complete this course may wish to continue their education into the CHC42021 – Certificate IV in Community Services and a range of other related community services qualifications.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures</p></div></div> </details>',
