UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community-based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualised service planning and delivery.</p><p>Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.</p><p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Aged Care Activity Worker</li><li>Care Service Team Leader</li><li>Care Supervisor (Aged Care)</li><li>Coordinator of Volunteers (Services to Older People)</li><li>Disability Officer – Day Support </li><li>Disability Team Leader </li><li>Leisure and Therapy Assistant </li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>CHCADV001</p></td><td><p>Facilitate the interests and rights of clients</p></td><td><p>Core</p></td></tr><tr><td><p>CHCAGE001</p></td><td><p>Facilitate the empowerment of older people</p></td><td><p>Core</p></td></tr><tr><td><p>CHCAGE003</p></td><td><p>Coordinate services for older people</p></td><td><p>Core</p></td></tr><tr><td><p>CHCAGE004</p></td><td><p>Implement interventions with older people at risk</p></td><td><p>Core</p></td></tr><tr><td><p>CHCAGE005</p></td><td><p>Provide support to people living with dementia</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS006</p></td><td><p>Facilitate individual service planning and delivery</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS011</p></td><td><p>Meet personal support needs</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS023</p></td><td><p>Support independence and wellbeing</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS025</p></td><td><p>Support relationships with carers and families</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIV001</p></td><td><p>Work with diverse people</p></td><td><p>Core</p></td></tr><tr><td><p>CHCLEG003</p></td><td><p>Manage legal and ethical compliance</p></td><td><p>Core</p></td></tr><tr><td><p>CHCPAL001</p></td><td><p>Deliver care services using a palliative approach</p></td><td><p>Core</p></td></tr><tr><td><p>CHCPRP001</p></td><td><p>Develop and maintain networks and collaborative partnerships</p></td><td><p>Core</p></td></tr><tr><td><p>HLTAAP001</p></td><td><p>Recognise healthy body systems</p></td><td><p>Core</p></td></tr><tr><td><p>HLTWHS002</p></td><td><p>Follow safe work practices for direct client care</p></td><td><p>Core</p></td></tr><tr><td><p>CHCAGE002</p></td><td><p>Implement falls prevention strategies</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCCCS017</p></td><td><p>Provide loss and grief support</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCMHS001</p></td><td><p>Work with people with mental health issues</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of community services and ageing support roles.</p><p>Students who complete this course may wish to continue their education into CHC52015 Diploma of Community Services or a range of other community services qualifications.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
