UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals in a range of community settings and peoples’ homes, who provide support in a manner that empowers people with disabilities to achieve greater levels of independence, self-reliance, community participation and wellbeing. Workers promote a person-centred approach, work according to and may contribute to an individualised plan, and work without direct supervision. They may be required to supervise and/or coordinate a small team.<br/>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Disability support worker</li><li>Community-based support officer</li><li>Disability team leader</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td><p>Code</p></td><td><p>Core/Elective</p></td></tr><tr><td><p>HLTWHS003 Maintain work health and safety</p></td><td><p>Core</p></td></tr><tr><td><p>CHCLEG003 Manage legal and ethical compliance</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS044 Follow established person-centred behaviour supports</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIS017 Facilitate community participation and social inclusion</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIS018 Facilitate ongoing skills development using a person-centred approach</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIS019 Provide person-centred services to people with disability with complex needs</p></td><td><p>Core</p></td></tr><tr><td><p>CHCMHS001 Work with people with mental health issues</p></td><td><p>Core</p></td></tr><tr><td><p>CHCADV001 Facilitate the interests and rights of clients</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCDIS015 <br/>Develop and provide person-centred service responses</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBLDR411 Demonstrate leadership in the workplace</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of disability work roles. Roles may also have a leadership function.</p><p>Students who complete this course may wish to continue their education into the CHC52021 Diploma of Community Services and a range of other community services related Diplomas.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures</p></div></div> </details>',
