    offshore_tuition_fee = 11900,
    enrolment_fee = 200,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p><ul><li>Entry to this qualification is open to individuals:</li></ul><ol><li>Completion of: CHC33021 Certificate III in Individual Support (Disability) OR</li><li>Completion of: CHC33015 Certificate III in Individual Support (Disability) OR</li><li>Completion of: CHC30408 Certificate III in Disability PLUS the CHCSS00125 Entry to Certificate IV in Disability Support Skill Set.</li></ol></div></div> </details>',
    apply_form = 'https://vie.edu.au/certificate-iv-in-disability',
    updated_at = NOW()
WHERE cricos_course_code = '112349F';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of educators in early childhood education and care who work in regulated children’s education and care services in Australia. Educators at this level are responsible for designing and implementing curriculum that meets the requirements of an approved learning framework and for maintaining compliance in other areas of service operations. They use specialised knowledge and analyse and apply theoretical concepts to diverse work situations. They may have responsibility for supervision of volunteers or other educators.</p><p>Early childhood educators work in long day care centres, family day care, pre-schools or kindergartens.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Family Day Care Educator</li><li>Kindergarten Assistant</li><li>Long Day Care Educator</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td>SN</td><td>Unit Code</td><td>CHC50121 Diploma of Early Childhood Education and Care</td><td>Core/ Elective</td><td>Hours</td></tr><tr><td>1</td><td>BSBTWK502</td><td>Manage team effectiveness</td><td>Core</td><td>60</td></tr><tr><td>2</td><td>CHCECE041</td><td>Maintain a safe and healthy environment for children</td><td>Core</td><td>60</td></tr><tr><td>3</td><td>CHCECE045</td><td>Foster positive and respectful interactions and behaviour in children</td><td>Core</td><td>80</td></tr><tr><td>4</td><td>CHCECE046</td><td>Implement strategies for the inclusion of all children</td><td>Core</td><td>60</td></tr><tr><td>5</td><td>CHCECE047</td><td>Analyse information to inform children’s learning</td><td>Core</td><td>60</td></tr><tr><td>6</td><td>CHCPRP003</td><td>Reflect on and improve own professional practice</td><td>Core</td><td>80</td></tr><tr><td>7</td><td>BSBPEF502</td><td>Develop and use emotional intelligence</td><td>Elective</td><td>60</td></tr><tr><td>8</td><td>BSBSTR501</td><td>Establish innovative work environments</td><td>Elective</td><td>60</td></tr><tr><td>9</td><td>CHCDIV003</td><td>Manage and promote diversity</td><td>Elective</td><td>80</td></tr><tr><td>10</td><td>CHCECE042</td><td>Foster holistic early childhood learning, development and wellbeing</td><td>Core</td><td>60</td></tr><tr><td>11</td><td>CHCECE043</td><td>Nurture creativity in children</td><td>Core</td><td>60</td></tr><tr><td>12</td><td>CHCECE049</td><td>Embed environmental responsibility in service operations</td><td>Core</td><td>40</td></tr><tr><td>13</td><td>CHCECE050</td><td>Work in partnership with children’s families</td><td>Core</td><td>40</td></tr><tr><td>14</td><td>CHCECE044</td><td>Facilitate compliance in a children’s education and care service</td><td>Core</td><td>60</td></tr><tr><td>15</td><td>CHCECE048</td><td>Plan and implement children’s education and care curriculum</td><td>Core</td><td>60</td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are as an Educator in an Early Childhood Education and Care setting.</p><p>Students who complete this course may wish to continue their education into higher education qualifications in early childhood education and care.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
