    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p><p>At this level, workers have specialised skills in community services and work autonomously within their scope of practice under broad directions from senior management.</p><p>Workers support people to make change in their lives to improve personal and social wellbeing and may also have responsibility for the supervision of other workers and volunteers. They may also undertake case management and program coordination.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><p>This course will give you the ability to gain employment in different roles as a community services worker. This roles may include:<br/>• Child Protection Case Manager<br/>• Housing Worker<br/>• Youth Worker<br/>• Support Coordinator (Disability)<br/>• Assistant Community Worker<br/>• Coordinator of Volunteer Work<br/>• Family Support Worker<br/>• Welfare Support Worker<br/>• Mental Health Support Worker<br/>• Community Program Coordinator<br/>and many other similar roles.</p></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td><p><strong>Unit</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr><tr><td><p>CHCCCS004</p></td><td><p>Assess co-existing needs</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS007</p></td><td><p>Develop and implement service programs</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCCS019</p></td><td><p>Recognise and respond to crisis situations</p></td><td><p>Core</p></td></tr><tr><td><p>CHCCSM013</p></td><td><p>Facilitate and review case management</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDEV005</p></td><td><p>Analyse impacts of sociological factors on people in community work and services</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDFV001</p></td><td><p>Recognise and respond appropriately to domestic and family violence</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIV001</p></td><td><p>Work with diverse people</p></td><td><p>Core</p></td></tr><tr><td><p>CHCDIV002</p></td><td><p>Promote Aboriginal and/or Torres Strait Islander cultural safety</p></td><td><p>Core</p></td></tr><tr><td><p>CHCLEG003</p></td><td><p>Manage legal and ethical compliance</p></td><td><p>Core</p></td></tr><tr><td><p>CHCMGT005</p></td><td><p>Facilitate workplace debriefing and support processes</p></td><td><p>Core</p></td></tr><tr><td><p>CHCPRP003</p></td><td><p>Reflect on and improve own professional practice</p></td><td><p>Core</p></td></tr><tr><td><p>HLTWHS003</p></td><td><p>Maintain work health and safety</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPEF502</p></td><td><p>Develop and use emotional intelligence</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBTWK503</p></td><td><p>Manage meetings</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBPEF401</p></td><td><p>Manage personal health and wellbeing</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCPOL003</p></td><td><p>Research and apply evidence to practice</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCCSL002</p></td><td><p>Apply specialist interpersonal and counselling skills</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCMGT003</p></td><td><p>Lead the work team</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCPRP001</p></td><td><p>Develop and maintain networks and collaborative partnerships</p></td><td><p>Elective</p></td></tr><tr><td><p>CHCDIV003</p></td><td><p>Manage and promote diversity</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in community services roles that focus on the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p><p>Students who complete this course may wish to continue their education into the Advanced Diploma of Community Sector Management or higher education qualifications in community services management.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 23800,
    enrolment_fee = 200,
    materials_fee = 2000,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>Educated for 5 years in an English – speaking country.</li><li>Successful completion of an English Placement Test at IELTS level 6.0</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/diploma-of-community-services',
    updated_at = NOW()
WHERE cricos_course_code = '112522J';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the job roles of workers in the accounting industry, including BAS Agents and contract bookkeepers; and of those employees performing bookkeeping tasks for organisations in a range of industries. It includes preparing and lodging business and instalment activity statements and providing advice or dealing with the Commissioner on behalf of a taxpayer in relation to activity statements. Individuals in these roles apply theoretical and specialist knowledge and skills to work autonomously, and exercise judgement in completing routine and non-routine activities.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Bookkeeper</li><li>Finance Sector Supervisor</li><li>Accounts Supervisor </li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr><tr><td><p>FNSACC421</p></td><td><p>Prepare financial reports</p></td><td><p>Core</p></td></tr><tr><td><p>BSBTEC302</p></td><td><p>Design and produce spreadsheets</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC322</p></td><td><p>Administer subsidiary accounts and ledgers</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC412</p></td><td><p>Prepare operational budgets</p></td><td><p>Core</p></td></tr><tr><td><p>FNSTPB411</p></td><td><p>Complete business activity and instalment activity statements</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC426</p></td><td><p>Set up and operate computerised accounting systems</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC414</p></td><td><p>Prepare financial statements for non-reporting entities</p></td><td><p>Core</p></td></tr><tr><td><p>FNSTPB412</p></td><td><p>Establish and maintain payroll systems</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC418</p></td><td><p>Work effectively in the accounting and bookkeeping industry</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC321</p></td><td><p>Process financial transactions and extract interim reports</p></td><td><p>Core</p></td></tr><tr><td><p>BSBTEC301</p></td><td><p>Design and produce business documents</p></td><td><p> Elective</p></td></tr><tr><td><p>FNSACC405</p></td><td><p>Maintain inventory records</p></td><td><p> Elective</p></td></tr><tr><td><p>BSBWRT311</p></td><td><p>Write simple documents</p></td><td><p> Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are entry level accounting roles across a range of industries.</p><p>Students who complete this course may wish to continue their education into FNS50222 Diploma of Accounting or into a range of other Diploma level qualifications.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 10500,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/certificate-iv-in-accounting-and-bookkeeping',
    updated_at = NOW()
WHERE cricos_course_code = '110019G';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects professional accounting job roles in financial services and other industries, including tax agents, accounts payable and accounts receivable officers, payroll service providers, and employees performing a range of accounting tasks for organisations in a range of industries. Individuals in these roles apply solutions to a range of often complex problems and analyse and evaluate information from a variety of sources. They apply initiative to plan, coordinate and evaluate their own work and provide guidance to others within defined guidelines.</p><p><strong>Licensing/Regulatory Information</strong></p><p>Work functions in the occupational areas where this qualification may be used are subject to regulatory requirements. Refer to the FNS Financial Services Training Package Companion Volume Implementation Guide or the relevant regulator for specific guidance on requirements.</p><p>This qualification includes units that comprise an approved Tax Practitioner Board (<a href="https://web.archive.org/web/20260208020233/https://www.tpb.gov.au/home" rel="noopener" target="_blank">TPB</a>) course in Australian taxation law and commercial law, which are relevant for registration as a tax agent. Persons seeking registration with the TPB should check current registration requirements with the TPB, as registration requirements are reviewed regularly.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Finance Sector Manager</li><li>Assistant Accountant </li><li>Senior Payroll Officer</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBTEC402</p></td><td><p>Design and produce complex spreadsheets</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC521</p></td><td><p>Provide financial and business performance information</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC522</p></td><td><p>Prepare tax documentation for individuals</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC523</p></td><td><p>Manage budgets and forecasts</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC524</p></td><td><p>Prepare financial reports for corporate entities</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC526</p></td><td><p>Implement and maintain internal control procedures</p></td><td><p>Core</p></td></tr><tr><td><p>FNSACC527</p></td><td><p>Provide management accounting information</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR413</p></td><td><p>Lead effective workplace relationships</p></td><td><p> Elective</p></td></tr><tr><td><p>FNSINC513</p></td><td><p>Identify and apply complex ethical decision making to workplace situations</p></td><td><p> Elective</p></td></tr><tr><td><p>FNSACC505</p></td><td><p>Establish and maintain accounting information systems</p></td><td><p> Elective</p></td></tr><tr><td><p>BSBTWK503</p></td><td><p>– Manage meetings</p></td><td><p> Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are entry level accounting roles across a range of industries.</p><p>Students who complete this course may wish to continue their education into FNS60222 Advanced Diploma of Accounting or into a range of other Diploma level qualifications.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 11500,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>Educated for 5 years in an English – speaking country.</li><li>Successful completion of an English Placement Test at IELTS level 6.0</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/diploma-of-accounting',
