UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals working in accounting and seeking professional recognition, including tax agents, accounts managers and business analysts; and to employees performing a range of accounts management tasks for organisations in a range of industries. At this level individuals are expected to apply theoretical and technical skills in a range of situations and to display initiative and judgement in planning activities. They have autonomy in performing complex operations and can be responsible for planning, coordinating, and evaluating the work of others within broad but generally well-defined parameters.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Financial Risk Manager</li><li>Paraplanner </li><li>Accounting Manager</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>On Campus</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>FNSACC634</p></td><td><p>Monitor corporate governance activities</p></td><td><p>Core</p></td></tr><tr><td><p>FNSINC611</p></td><td><p>Apply economic principles to work in the financial services industry</p></td><td><p>Core</p></td></tr><tr><td><p>FNSINC612</p></td><td><p>Interpret and use financial statistics and tools</p></td><td><p>Core</p></td></tr><tr><td><p>BSBLDR523</p></td><td><p>Lead and manage effective workplace relationships</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBOPS502</p></td><td><p>Manage business operational plans</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBPEF502</p></td><td><p>Develop and use emotional intelligence</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBTWK502</p></td><td><p>Manage team effectiveness</p></td><td><p>Elective</p></td></tr><tr><td><p>FNSACC601</p></td><td><p>Prepare and administer tax documentation for legal entities</p></td><td><p>Elective</p></td></tr><tr><td><p><strong>FNSACC521</strong></p></td><td><p><strong>Provide financial and business performance information</strong></p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p><strong>FNSACC522</strong></p></td><td><p><strong>Prepare tax documentation for individuals</strong></p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p><strong>FNSACC524</strong></p></td><td><p><strong>Prepare financial reports for corporate entities</strong></p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p><strong>FNSACC526</strong></p></td><td><p><strong>Implement and maintain internal control procedures</strong></p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p><strong>FNSACC527</strong></p></td><td><p><strong>Provide management accounting information</strong></p></td><td><p><strong>Elective</strong></p></td></tr><tr><td><p><strong>BSBTWK503</strong></p></td><td><p><strong>Manage meetings</strong></p></td><td><p><strong>Elective</strong></p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options include tax agents, accounts managers and business analysts and other accounting management roles across a range of industries.</p><p>Students who complete this course may wish to continue their education into a range of other Graduate Diploma level qualifications in accounting or financial services.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 13500,
    enrolment_fee = 200,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/advanced-diploma-of-accounting',
