UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have established specialised skills in a technical ICT function.</p><p>Individuals in these roles carry out moderately complex tasks in specialist fields, working independently, as part of a team or leading deliverables with others. They may apply their skills across a wide range of industries, business functions and departments, or as a business owner (sole trader/contractor).</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><p>The skills required for these roles may include, but are not restricted to:</p><ul><li><strong>Advanced Networking:</strong> configuring and managing virtual computing environments, and security within ICT networks.</li><li><strong>Cyber Security:</strong> protecting sensitive data and information through security architecture and developing disaster recovery and contingency plans.</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr></thead><tbody><tr><td><p>BSBCRT512</p></td><td><p>Originate and develop concepts</p></td><td><p>Core</p></td></tr><tr><td><p>BSBXCS402</p></td><td><p>Promote workplace cyber security awareness and best practices</p></td><td><p>Core</p></td></tr><tr><td><p>BSBXTW401</p></td><td><p>Lead and facilitate a team</p></td><td><p>Core</p></td></tr><tr><td><p>ICTICT517</p></td><td><p>Match ICT needs with the strategic direction of the organisation</p></td><td><p>Core</p></td></tr><tr><td><p>ICTICT532</p></td><td><p>Apply IP, ethics and privacy policies in ICT environments</p></td><td><p>Core</p></td></tr><tr><td><p>ICTSAS527</p></td><td><p>Manage client problems</p></td><td><p>Core</p></td></tr><tr><td><p>ICTNWK540</p></td><td><p>Design, build and test network servers</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTNWK529</p></td><td>Install and manage complex ICT networks</td><td><p>Elective</p></td></tr><tr><td><p>ICTNWK536</p></td><td><p>Plan, implement and test enterprise communication solutions</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTNWK546</p></td><td><p>Manage network security</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTNWK557</p></td><td><p>Configure and manage advanced virtual computing environments</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTNWK559</p></td><td><p>Install an enterprise virtual computing environment</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTSAS526</p></td><td><p>Review and update disaster recovery and contingency plans</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBLDR523</p></td><td><p>Lead and manage effective workplace relationships</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBTWK502</p></td><td><p>Manage team effectiveness</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBPMG532</p></td><td><p>Manage project quality</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTSAS524</p></td><td><p>Develop, implement and evaluate an incident response plan</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTCYS407</p></td><td><p>Gather, analyse and interpret threat data</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTCYS610</p></td><td><p>Protect critical infrastructure for organisations</p></td><td><p>Elective</p></td></tr><tr><td><p>ICTCYS613</p></td><td><p>Utilise design methodologies for security architecture</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of IT related roles.</p><p>Students who complete this course may wish to continue their education into a range of advanced diploma qualifications such as the ICT60220 Advanced Diploma of Information Technology.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p><p>Students who complete this course may wish to continue their education into a range of advanced diploma qualifications such as the ICT60220 Advanced Diploma of Information Technology.</p></div></div> </details>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 18000,
    enrolment_fee = 200,
    materials_fee = 450,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>Educated for 5 years in an English – speaking country.</li><li>Successful completion of an English Placement Test at IELTS level 6.0</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p></div></div> </details>',
