    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have significant experience in specialist technical skills, or managerial business and people management skills.</p><p>Individuals in these roles carry out complex tasks in a specialist field, working independently, leading a team or a strategic direction of a business. They apply their skills across a wide range of industries and business functions, or as a business owner (sole trader/contractor).</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><p>The skills required for these roles may include, but are not restricted to:</p><ul><li><strong>Cyber Security:</strong> protecting sensitive data and information through security architecture and developing disaster recovery and contingency plans.</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><thead><tr><td><p><strong>Code </strong></p></td><td><p><strong>Title </strong></p></td><td><p><strong>Core or Elective </strong></p></td></tr></thead><tbody><tr><td><p>BSBCRT611 </p></td><td><p>Apply critical thinking for complex problem solving </p></td><td><p>Core </p></td></tr><tr><td><p>BSBXCS402 </p></td><td><p>Promote workplace cyber security awareness and best practices </p></td><td><p>Core </p></td></tr><tr><td><p>ICTICT608 </p></td><td><p>Interact with clients on a business level </p></td><td><p>Core </p></td></tr><tr><td><p>ICTICT618 </p></td><td><p>Manage IP, ethics and privacy in ICT environments </p></td><td><p>Core </p></td></tr><tr><td><p>ICTSAD609 </p></td><td><p>Plan and monitor business analysis activities in an ICT environment </p></td><td><p>Core </p></td></tr><tr><td><p>BSBTWK502 </p></td><td><p>Manage team effectiveness </p></td><td><p>Core </p></td></tr><tr><td><p>ICTNWK540 </p></td><td><p>Design, build and test network servers </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTNWK559 </p></td><td><p>Install an enterprise virtual computing environment </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTCYS612 </p></td><td><p>Design and implement virtualised cyber security infrastructure for organisations </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTCYS604 </p></td><td><p>Implement best practices for identity management </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTCYS606 </p></td><td><p>Evaluate an organisation’s compliance with cyber security standards and law </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTCYS608 </p></td><td><p>Perform cyber security risk assessments </p></td><td><p>Elective </p></td></tr><tr><td><p>BSBPMG532 </p></td><td><p>Manage project quality </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTNWK546 </p></td><td><p>Manage network security </p></td><td><p>Elective </p></td></tr><tr><td><p>ICTNWK557 </p></td><td><p>Configure and manage advanced virtual computing environments </p></td><td><p>Elective </p></td></tr><tr><td><p>BSBLDR523 </p></td><td><p>Lead and manage effective workplace relationships </p></td><td><p>Elective </p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>Potential employment options are in a range of IT related roles.</p><p>Students who complete this course may wish to continue their education into higher education qualifications in information technology.</p></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures.</p></div></div> </details>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 12000,
    enrolment_fee = 200,
    materials_fee = 350,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/advanced-diploma-of-information-technology',
    updated_at = NOW()
WHERE cricos_course_code = '107867D';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><details open=""> <div><div><p>This qualification reflects the role of an individual working as a senior civil works designer or a para-professional designer, who supports professional engineers. They perform tasks that are broad, specialised, complex and technical and include strategic areas and initiating activities. They are responsible for the design of complex projects to ensure the implementation of the client’s site requirements and are required to demonstrate self-directed application of theoretical and technical knowledge and initiate solutions to technical problems or management requirements.</p></div></div> </details><h4>Career Prospects</h4><details> <div><div><ul><li>Civil Engineering Construction Supervisor</li><li>Civil Engineering Draftsperson</li><li>Civil Engineering Design Draftsperson</li><li>Civil Engineering Technician</li><li>Senior Civil Works Designer</li></ul></div></div> </details><h4>Study Mode</h4><details> <div><div><p>This program is delivered in the classroom and through structured self-study.</p></div></div> </details><h4>Units of Competency</h4><details> <div><div><table><tbody><tr><td><p><strong>Code</strong></p></td><td><p><strong>Title</strong></p></td><td><p><strong>Core or Elective</strong></p></td></tr><tr><td><p>BSBPMG632</p></td><td><p>Manage program risk</p></td><td><p>Core</p></td></tr><tr><td><p>BSBTWK502</p></td><td><p>Manage team effectiveness</p></td><td><p>Core</p></td></tr><tr><td><p>BSBWHS616</p></td><td><p>Apply safe design principles to control WHS risks</p></td><td><p>Core</p></td></tr><tr><td><p>RIICWD601E</p></td><td><p>Manage civil works design processes</p></td><td><p>Core</p></td></tr><tr><td><p>RIIQUA601E</p></td><td><p>Establish and maintain a quality system</p></td><td><p>Core</p></td></tr><tr><td><p>BSBPMG532</p></td><td><p>Manage project quality</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBPMG534</p></td><td><p>Manage project human resources</p></td><td><p>Elective</p></td></tr><tr><td><p>BSBSTR601</p></td><td><p>Manage innovation and continuous improvement</p></td><td><p>Elective</p></td></tr><tr><td><p>RIICWD507D</p></td><td><p>Prepare detailed geotechnical design</p></td><td><p>Elective</p></td></tr><tr><td><p>MEM30031</p></td><td><p>Operate computer-aided design (CAD) system to produce basic drawing elements</p></td><td><p>Elective</p></td></tr><tr><td><p>RIICWD533E</p></td><td><p>Prepare detailed design of civil concrete structures</p></td><td><p>Elective</p></td></tr><tr><td><p>RIICWD534E</p></td><td><p>Prepare detailed design of civil steel structures.</p></td><td><p>Elective</p></td></tr></tbody></table></div></div> </details><h4>Pathways Information</h4><details> <div><div><p>After completion of RII60520 Advanced Diploma of Civil Construction Design. Students may wish to undertake other related course or a pathway to higher education such as:</p><ol><li>Bachelor of Civil Construction.</li><li>Bachelor of Design</li></ol></div></div> </details><h4>Course Credit</h4><details> <div><div><p>Students may apply for recognition of existing qualifications or skills, knowledge, and experience (credit transfer or recognition of prior learning). The granting of course credit may affect course fees, as well as the duration of the course.</p><p>This process is outlined in Victorian Institute of Education Student Enrolment and Completion Policy and Associated Procedures and Training and Assessment Policy &amp; Associated Procedures</p></div></div> </details>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 24000,
    enrolment_fee = 200,
    materials_fee = 2000,
    entry_requirements = '<h4>Entry Requirements</h4><details> <div><div><p>Victorian Institute of Education has the following entry requirements. International students must:</p><ul><li>Be at least 18 years of age and have completed Year 12 or equivalent.</li><li>Participate in diagnostic activities (e.g., LLN test and pre-enrolment screening) to determine suitability for the course and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ol><li>The student has successfully completed a foundation course in Australia</li><li>The student has successfully completed at least 6 months of a Certificate IV level course in an Australian RTO</li><li>Educated for 5 years in an English-speaking country</li><li>Successful completion of an English Placement Test</li></ol></li></ul><p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0</p></div></div> </details>',
    apply_form = 'https://vie.edu.au/advanced-diploma-of-civil-construction-design',
